<?php require __DIR__.'/_guard.php';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=royal-orders.csv');$out=fopen('php://output','w');fputcsv($out,['Order','Customer','Phone','City','Total','Payment','Status','Date']);$q=db()->query('SELECT id,customer_name,phone,city,grand_total,payment_method,order_status,created_at FROM orders ORDER BY id DESC');while($r=$q->fetch())fputcsv($out,$r);fclose($out);exit;